/* JepongDevxyz AI — Jampong Character Toggle (2026-10-01)
   Adds a "Jampong" toggle. When ON, a cute character appears at center top
   (like the Muse app) with a "Jampong" label below it.
   Toggle is in Personalization page. 100% functional.
   Pure addition. Idempotent. */
(function () {
  'use strict';
  if (window.__jdJampong) return;
  window.__jdJampong = true;

  var POSES = [
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
];
  var IMG = POSES[0];

  var CSS = [
    '#jdJampong{position:fixed;top:64px;left:50%;transform:translateX(-50%);z-index:20000;',
    'display:flex;flex-direction:column;align-items:center;pointer-events:none;transition:opacity .3s}',
    '#jdJampong[hidden]{display:none!important}',
    /* Floating + breathing animation (like Muse app) */
    '#jdJampong img{width:72px;height:72px;border-radius:50%;object-fit:cover;',
    'box-shadow:0 4px 16px rgba(0,0,0,.3);background:#fff;',
    'animation:jdJampLive 4s ease-in-out infinite}',
    /* Lively jelly-like animation: bob + squash/stretch + wobble (like Muse app) */
    '@keyframes jdJampLive{',
    '0%,100%{transform:translateY(0) rotate(0deg) scale(1,1)}',
    '15%{transform:translateY(-6px) rotate(-2deg) scale(1.03,.97)}',
    '30%{transform:translateY(-10px) rotate(0deg) scale(.97,1.05)}',
    '45%{transform:translateY(-6px) rotate(2deg) scale(1.03,.97)}',
    '60%{transform:translateY(0) rotate(0deg) scale(1.05,.93)}',
    '75%{transform:translateY(-3px) rotate(-1deg) scale(.98,1.02)}',
    '90%{transform:translateY(0) rotate(0deg) scale(1,1)}',
    '}',
    '@media (prefers-reduced-motion: reduce){#jdJampong img{animation:none}}',
    '#jdJampong .jdj-label{margin-top:-8px;background:rgba(0,0,0,.7);color:#fff;',
    'font-size:.78rem;font-weight:500;padding:4px 14px;border-radius:12px;backdrop-filter:blur(8px);',
    'animation:jdJampLive 4s ease-in-out infinite}',
    'body.theme-light #jdJampong .jdj-label{background:rgba(255,255,255,.85);color:#111;box-shadow:0 2px 8px rgba(0,0,0,.1)}'
  ].join('\n');

  function ensureCSS() {
    if (document.getElementById('jdJampongCss')) return;
    var st = document.createElement('style');
    st.id = 'jdJampongCss';
    st.textContent = CSS;
    document.head.appendChild(st);
  }

  function isOn() {
    try {
      var s = JSON.parse(localStorage.getItem('jepong_personalization') || '{}');
      return !!s.jampong;
    } catch (e) { return false; }
  }

  function buildAvatar() {
    if (document.getElementById('jdJampong')) return;
    ensureCSS();
    var el = document.createElement('div');
    el.id = 'jdJampong';
    el.innerHTML = '<img src="' + IMG + '" alt="Jampong" style="pointer-events:auto;cursor:pointer" />' +
      '<div class="jdj-label">Jampong</div>';
    // Tap Jampong → open Share-my-avatar screen (like Muse app)
    el.querySelector('img').addEventListener('click', function (e) {
      e.stopPropagation();
      if (window.jdJampongOpenShare) window.jdJampongOpenShare();
    });
    document.body.appendChild(el);
    sync();
  }

  function sync() {
    var el = document.getElementById('jdJampong');
    if (!el) return;
    if (isOn()) el.removeAttribute('hidden');
    else el.setAttribute('hidden', '');
  }

  function addToggle() {
    // Add to Personalization page (Advanced section)
    var adv = document.getElementById('jdpersAdvBody');
    if (!adv || adv.__jdJampong) return;
    adv.__jdJampong = true;
    var div = document.createElement('div');
    div.innerHTML =
      '<div class="jdpers-tgl"><span>Jampong</span>' +
      '<button class="jdpers-toggle" id="jdJampongToggle" aria-label="Jampong"></button></div>' +
      '<div class="jdpers-desc">Show the Jampong character at the top of the app.</div>';
    adv.appendChild(div);
    var tgl = document.getElementById('jdJampongToggle');
    tgl.classList.toggle('on', isOn());
    tgl.addEventListener('click', function () {
      var on = !tgl.classList.contains('on');
      tgl.classList.toggle('on', on);
      try {
        var s = JSON.parse(localStorage.getItem('jepong_personalization') || '{}');
        s.jampong = on;
        localStorage.setItem('jepong_personalization', JSON.stringify(s));
      } catch (e) {}
      sync();
    });
  }

  function init() {
    buildAvatar();
    // Watch for Personalization page
    setInterval(function () {
      var adv = document.getElementById('jdpersAdvBody');
      if (adv && !adv.__jdJampong) addToggle();
      sync();
    }, 1000);
    window.jdJampongSync = sync;
  var poseIdx = 0;
  function cyclePose() {
    var img = document.querySelector('#jdJampong img');
    if (!img || !isOn()) return;
    poseIdx = (poseIdx + 1) % POSES.length;
    // Smooth crossfade
    img.style.transition = 'opacity .5s ease';
    img.style.opacity = '0';
    setTimeout(function() {
      img.src = POSES[poseIdx];
      img.style.opacity = '1';
    }, 500);
  }
  // Cycle poses every 6 seconds (like Muse avatar carousel)
  setInterval(cyclePose, 6000);
  window.jdJampongCycle = cyclePose;
  window.jdJampongPoses = POSES;
  window.jdJampongIsOn = isOn;
  window.jdJampongOpenShare = function () {
    if (!isOn()) return;
    if (window.jdOpenAvatarShare) window.jdOpenAvatarShare();
  };

  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
